import { Col, Container, Row } from 'react-bootstrap'

const Footer = () =>{


    return(
        <Container style={{backgroundColor: 'grey'}}>
            <Row>
                <Col className='text-center py-3'>
                    Hello
                </Col>
            </Row>
        </Container>
    )
}

export default Footer;
